import React, { useState } from 'react';
import { Bell, MessageSquare, Phone, Mail, CheckCheck, Trash2, Filter, AlertCircle, Info, CheckCircle, ArrowRight } from 'lucide-react';
import { NavLink } from 'react-router-dom';
import './Notifications.css';

const notifs = [
  { id: 1, type: 'alert', icon: AlertCircle, title: 'High No-Show Risk Detected', msg: 'Patient Vikas Kumar (Cardiology) has a 78% no-show risk for tomorrow\'s appointment.', time: '2 min ago', read: false, color: '#EF4444', bg: '#FEE2E2' },
  { id: 2, type: 'success', icon: CheckCircle, title: 'Appointment Confirmed', msg: 'John Smith\'s appointment with Dr. Sarah Johnson on May 16 at 5:00 PM has been confirmed.', time: '15 min ago', read: false, color: '#10B981', bg: '#D1FAE5' },
  { id: 3, type: 'whatsapp', icon: MessageSquare, title: 'WhatsApp Reminders Sent', msg: '12 WhatsApp appointment reminders sent successfully. 8 patients have confirmed.', time: '30 min ago', read: false, color: '#25D366', bg: '#DCFCE7' },
  { id: 4, type: 'info', icon: Info, title: 'New Patient Registration', msg: 'Jennifer Martinez (ID: PT001241) has been registered and assigned to Dr. Sarah Johnson.', time: '1 hour ago', read: true, color: '#3B82F6', bg: '#DBEAFE', link: '/patients' },
  { id: 5, type: 'alert', icon: AlertCircle, title: 'Appointment Cancelled', msg: 'Lisa Anderson cancelled her appointment with Dr. James Wilson scheduled for May 18.', time: '2 hours ago', read: true, color: '#F59E0B', bg: '#FEF3C7' },
  { id: 6, type: 'sms', icon: Phone, title: 'SMS Reminders Pending', msg: '8 SMS reminders are scheduled to be sent at 6:00 PM today.', time: '3 hours ago', read: true, color: '#6366F1', bg: '#EEF2FF' },
  { id: 7, type: 'email', icon: Mail, title: 'Email Reports Generated', msg: 'Weekly analytics report for May 9–15 has been generated and sent to admin@hospital.com.', time: '5 hours ago', read: true, color: '#EF4444', bg: '#FEE2E2' },
  { id: 8, type: 'success', icon: CheckCircle, title: 'Schedule Updated', msg: 'Dr. Amit Verma\'s schedule has been updated. On-leave period: May 18–22.', time: '6 hours ago', read: true, color: '#10B981', bg: '#D1FAE5' },
  { id: 9, type: 'info', icon: Info, title: 'System Backup Complete', msg: 'Daily system backup completed successfully at 2:00 AM. All data is secure.', time: '8 hours ago', read: true, color: '#3B82F6', bg: '#DBEAFE' },
  { id: 10, type: 'alert', icon: Bell, title: 'Peak Hours Alert', msg: 'Tomorrow\'s 10 AM – 1 PM slot is at 95% capacity. Consider opening additional slots.', time: '9 hours ago', read: true, color: '#F59E0B', bg: '#FEF3C7' },
];

const filters = ['All', 'Unread', 'Alerts', 'Appointments', 'Reminders', 'System'];

export default function Notifications() {
  const [active, setActive] = useState('All');
  const [items, setItems] = useState(notifs);

  const unread = items.filter(n => !n.read).length;
  const filtered = items.filter(n => active === 'All' || (active === 'Unread' && !n.read) || (active === 'Alerts' && n.type === 'alert'));

  const markAll = () => setItems(prev => prev.map(n => ({ ...n, read: true })));
  const markRead = (id) => setItems(prev => prev.map(n => n.id === id ? { ...n, read: true } : n));
  const remove = (id) => setItems(prev => prev.filter(n => n.id !== id));

  return (
    <div className="notifs-page fade-in">
      <div className="page-header" style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between' }}>
        <div>
          <h1>Notifications <span className="notif-count">{unread}</span></h1>
          <p>Stay updated with all system alerts and reminders</p>
        </div>
        <div style={{ display: 'flex', gap: 10 }}>
          <button className="btn btn-ghost" onClick={markAll}><CheckCheck size={14} /> Mark All Read</button>
          <button className="btn btn-ghost"><Filter size={14} /> Filter</button>
        </div>
      </div>

      <div className="notif-layout">
        <div className="notif-main">
          <div className="notif-filters card fade-in-1">
            {filters.map(f => (
              <button key={f} className={`nf-btn ${active === f ? 'active' : ''}`} onClick={() => setActive(f)}>
                {f} {f === 'Unread' && unread > 0 && <span className="nf-badge">{unread}</span>}
              </button>
            ))}
          </div>

          <div className="notif-list fade-in-2">
            {filtered.map(n => (
              <div key={n.id} className={`notif-item card ${n.read ? 'read' : 'unread'}`}>
                <div className="notif-icon" style={{ background: n.bg, color: n.color }}>
                  <n.icon size={18} />
                </div>
                <div className="notif-content">
                  <div className="notif-header">
                    <p className="notif-title">{n.title}</p>
                    <div className="notif-actions">
                      <span className="notif-time">{n.time}</span>
                      {!n.read && <button className="notif-action-btn" onClick={() => markRead(n.id)} title="Mark as read"><CheckCheck size={13} /></button>}
                      <button className="notif-action-btn danger" onClick={() => remove(n.id)} title="Remove"><Trash2 size={13} /></button>
                    </div>
                  </div>
                  <p className="notif-msg">{n.msg}</p>
                  {n.link && (
                    <NavLink to={n.link} className="notif-link" onClick={() => markRead(n.id)}>
                      View details <ArrowRight size={11} />
                    </NavLink>
                  )}
                </div>
                {!n.read && <div className="unread-dot"></div>}
              </div>
            ))}
          </div>
        </div>

        <div className="notif-sidebar fade-in-3">
          <div className="card">
            <h3 style={{ fontSize: 14, marginBottom: 14 }}>Notification Summary</h3>
            {[
              { label: 'Total', value: items.length, color: 'var(--primary)' },
              { label: 'Unread', value: unread, color: 'var(--danger)' },
              { label: 'Alerts', value: items.filter(n => n.type === 'alert').length, color: 'var(--warning)' },
              { label: 'Today', value: 6, color: 'var(--success)' },
            ].map(s => (
              <div key={s.label} className="notif-stat">
                <span className="ns-label">{s.label}</span>
                <span className="ns-value" style={{ color: s.color }}>{s.value}</span>
              </div>
            ))}
          </div>

          <div className="card">
            <h3 style={{ fontSize: 14, marginBottom: 14 }}>Reminder Channels</h3>
            {[
              { icon: MessageSquare, label: 'WhatsApp', status: 'Active', count: 12, color: '#25D366' },
              { icon: Phone, label: 'SMS', status: 'Scheduled', count: 8, color: '#6366F1' },
              { icon: Phone, label: 'Voice Call', status: 'Active', count: 5, color: '#F59E0B' },
              { icon: Mail, label: 'Email', status: 'Active', count: 3, color: '#EF4444' },
            ].map(c => (
              <div key={c.label} className="channel-item">
                <div className="channel-icon" style={{ background: c.color + '20', color: c.color }}><c.icon size={15} /></div>
                <div style={{ flex: 1 }}>
                  <p style={{ fontSize: 13, fontWeight: 600 }}>{c.label}</p>
                  <p style={{ fontSize: 11, color: 'var(--text-secondary)' }}>{c.count} pending</p>
                </div>
                <span className={`badge ${c.status === 'Active' ? 'active' : 'warning'}`}>{c.status}</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}
